const b=$input.first().json.body;
if(!b || typeof b.text!=='string' || !b.text.trim() || b.text.length>5000 || typeof b.session_key!=='string' || !/^wa:[0-9]{5,30}:[0-9]{8,20}$/.test(b.session_key)) throw new Error('Solicitud WhatsApp inválida');
const context=typeof b.sales_context==='string'&&b.sales_context.length<=20000?b.sales_context:'{}';
return [{json:{text:b.text,session_key:b.session_key,sales_context:context}}];

const raw=$input.first().json.output;
if(typeof raw!=='string'||raw.length>15000)throw new Error('Respuesta IA inválida');
const a=JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));
if(!a||typeof a.reply!=='string'||!a.reply.trim()||a.reply.length>1500)throw new Error('Respuesta inválida');
const q=a.qualification||{},d=a.demo||{};
return [{json:{reply:a.reply.trim(),qualification:{businessFit:q.businessFit===true,commercialIntent:q.commercialIntent===true,interest:typeof q.interest==='string'?q.interest.slice(0,500):'',name:typeof q.name==='string'?q.name.slice(0,200):'',company:typeof q.company==='string'?q.company.slice(0,200):'',handoff:q.handoff===true},summary:typeof a.summary==='string'?a.summary.slice(0,1000):'',demo:{requested:d.requested===true,preferred_time:typeof d.preferred_time==='string'?d.preferred_time.slice(0,300):''}}}];
